/* ==UserStyle==
@name         Roblox Dark Blue Theme (Stylish Image Key Version)
@namespace    StylishThemes
@version      1.0.2
@description  Dark blue Roblox theme with customizable background (Stylish Image Key)
@author       You
@match        *://www.roblox.com/*
@match        *://web.roblox.com/*
==/UserStyle== */
@-moz-document domain("roblox.com") {
/* === Background image === */
  body, .container-main, .content, #container-main, .game-home-header, .game-home-header-content {
    background: url("/*[[background]]*/") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #d6e4ff !important;
  }

  /* Add a slight dark overlay so text stays readable */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(5, 10, 35, 0.6); /* dark blue transparent layer */
    z-index: -1;
  }

  /* Navbar and headers */
  .rbx-navbar, .navbar, .rbx-header {
    background-color: rgba(10, 15, 44, 0.8) !important;
    border-bottom: 1px solid #1c2b60 !important;
  }

  /* Text colors */
  h1, h2, h3, h4, h5, p, span, a, .text, .text-label {
    color: #cfe6ff !important;
  }

  /* Links */
  a {
    color: #7ab8ff !important;
  }
  a:hover {
    color: #a6d2ff !important;
  }

  /* Buttons */
  .btn-primary, .btn-control, .btn-common {
    background-color: rgba(26, 43, 109, 0.85) !important;
    color: #e0ecff !important;
    border: 1px solid #294599 !important;
  }
  .btn-primary:hover, .btn-control:hover, .btn-common:hover {
    background-color: rgba(35, 58, 140, 0.9) !important;
  }

  /* Cards and panels */
  .card-item, .game-card, .game-card-container, .panel {
    background-color: rgba(18, 26, 64, 0.8) !important;
    border-color: #1f2d6b !important;
  }

  /* Input fields */
  input, textarea {
    background-color: rgba(13, 21, 56, 0.8) !important;
    color: #cfe6ff !important;
    border: 1px solid #2a3a80 !important;
  }

  /* Sidebar (fixes white sidebar issue) */
  .sidebar, .left-col, .navigation-container, .nav-menu, #navigation {
    background-color: rgba(10, 15, 44, 0.85) !important;
    color: #d6e4ff !important;
  }

  /* Footer */
  footer, .footer-container {
    background-color: rgba(10, 15, 44, 0.8) !important;
    color: #a9c5ff !important;
  }
}
